package com.yeyamo_mobile.api.gamification_service.infrastructure.web;import org.springframework.context.annotation.*;import io.swagger.v3.oas.models.*;import io.swagger.v3.oas.models.info.Info;import io.swagger.v3.oas.models.security.*;
@Configuration public class OpenApiConfig{@Bean OpenAPI gamificationApi(){return new OpenAPI().info(new Info().title("YeYamo Gamification API").version("v1").description("XP, niveaux, badges, séries, passeport et récompenses")).components(new Components().addSecuritySchemes("bearerAuth",new SecurityScheme().type(SecurityScheme.Type.HTTP).scheme("bearer").bearerFormat("JWT"))).addSecurityItem(new SecurityRequirement().addList("bearerAuth"));}}
